export function installNativeFlowStepBefore({
  stepName,
  beforeStep,
  flowNames = [],
  step
} = {}) {
  if (!requiredString(stepName)) {
    throw new TypeError(
      "Native Flow extension stepName must be a non-empty string."
    );
  }

  if (!requiredString(beforeStep)) {
    throw new TypeError(
      "Native Flow extension beforeStep must be a non-empty string."
    );
  }

  if (
    !Array.isArray(flowNames) ||
    flowNames.length === 0 ||
    flowNames.some(flowName => !requiredString(flowName))
  ) {
    throw new TypeError(
      "Native Flow extension flowNames must be a non-empty array of Flow names."
    );
  }

  if (typeof step !== "function") {
    throw new TypeError(
      "Native Flow extension step must be a function."
    );
  }

  const flowSteps =
    globalThis.game
      ?.lancer
      ?.flowSteps;

  if (
    !flowSteps ||
    typeof flowSteps.get !== "function" ||
    typeof flowSteps.set !== "function"
  ) {
    throw new Error(
      "game.lancer.flowSteps registry is unavailable."
    );
  }

  const existingStep =
    flowSteps.get(stepName);

  if (
    existingStep &&
    existingStep !== step
  ) {
    throw new Error(
      `Native Lancer Flow step already exists with a different implementation: ${stepName}`
    );
  }

  if (!existingStep) {
    flowSteps.set(
      stepName,
      step
    );
  }

  const installedFlows =
    [];

  for (const flowName of flowNames) {
    const FlowConstructor =
      getNativeFlowConstructor(
        flowName
      );

    if (
      !Array.isArray(FlowConstructor.steps) ||
      !FlowConstructor.steps.includes(beforeStep)
    ) {
      throw new Error(
        `Native Lancer Flow ${flowName} does not contain required step ${beforeStep}.`
      );
    }

    if (
      !FlowConstructor.steps.includes(stepName)
    ) {
      FlowConstructor.insertStepBefore(
        beforeStep,
        stepName
      );
    }

    installedFlows.push(
      flowName
    );
  }

  return Object.freeze({
    stepName,
    beforeStep,
    flowNames:
      Object.freeze([
        ...installedFlows
      ])
  });
}

function getFlowStateData(flow) {

  this.current =
    null;


  /**
   * Actor-keyed reaction usage survives active-combatant changes so
   * out-of-turn reactions can be tracked against the actual reactor.
   */
  this.actorReactionUsage =
    new Map();


  /**
   * Reaction locks are actor keyed and combat scoped. Brace uses this
   * to suppress all Frame Conn reactions until its aftermath expires.
   */
  this.actorReactionLocks =
    new Map();
}


normalizeReactionActorKey(
  actorReference
) {
  const actorKey =
    typeof actorReference ===
      "string"
      ? actorReference
      : actorReference?.uuid ??
        actorReference?.id ??
        null;


  if (!actorKey) {
    throw new TypeError(
      "Frame Conn reaction tracking requires an actor reference."
    );
  }


  return String(actorKey);
}


reactionCombatContext(
  combat =
    globalThis.game?.combat
) {
  if (
    !combat?.id ||
    !combat.started ||
    !Number.isFinite(combat.round) ||
    !Number.isFinite(combat.turn)
  ) {
    return null;
  }


  return {
    combatId:
      combat.id,

    turnKey:
      `${combat.id}:${combat.round}:${combat.turn}`
  };
}


canUseReactionForActor(
  actorReference,
  actionId = null,
  {
    combat =
      globalThis.game?.combat
  } = {}
) {
  const actorKey =
    this.normalizeReactionActorKey(
      actorReference
    );


  const combatContext =
    this.reactionCombatContext(
      combat
    );


  if (!combatContext) {
    return {
      allowed:
        false,

      reason:
        "A reaction requires an active combat turn."
    };
  }


  const lock =
    this.actorReactionLocks.get(
      actorKey
    );


  if (
    lock?.combatId ===
    combatContext.combatId
  ) {
    return {
      allowed:
        false,

      reason:
        lock.reason ??
        "Reactions are currently unavailable for this actor."
    };
  }


  const usage =
    this.actorReactionUsage.get(
      actorKey
    );


  if (
    usage?.turnKey ===
    combatContext.turnKey
  ) {
    return {
      allowed:
        false,

      reason:
        "This actor has already taken a reaction during the current turn."
    };
  }


  return {
    allowed:
      true,

    reason:
      null,

    actorKey,

    actionId,

    ...combatContext
  };
}


useReactionForActor(
  actorReference,
  actionId = null,
  options = {}
) {
  const permission =
    this.canUseReactionForActor(
      actorReference,
      actionId,
      options
    );


  if (!permission.allowed) {
    throw new Error(
      permission.reason
    );
  }


  this.actorReactionUsage.set(
    permission.actorKey,
    {
      combatId:
        permission.combatId,

      turnKey:
        permission.turnKey,

      actionId:
        actionId ??
        null,

      usedAt:
        Date.now()
    }
  );


  return {
    ...this.actorReactionUsage.get(
      permission.actorKey
    )
  };
}


releaseReactionForActor(
  actorReference,
  actionId = null,
  {
    combat =
      globalThis.game?.combat
  } = {}
) {
  const actorKey =
    this.normalizeReactionActorKey(
      actorReference
    );


  const combatContext =
    this.reactionCombatContext(
      combat
    );


  const usage =
    this.actorReactionUsage.get(
      actorKey
    );


  if (
    !usage ||
    usage.turnKey !==
      combatContext?.turnKey ||
    (
      actionId &&
      usage.actionId !==
        actionId
    )
  ) {
    return false;
  }


  this.actorReactionUsage.delete(
    actorKey
  );


  return true;
}


setReactionLockForActor(
  actorReference,
  locked,
  {
    combat =
      globalThis.game?.combat,
    reason = null
  } = {}
) {
  const actorKey =
    this.normalizeReactionActorKey(
      actorReference
    );


  if (!locked) {
    this.actorReactionLocks.delete(
      actorKey
    );


    return false;
  }


  const combatId =
    combat?.id ??
    null;


  if (!combatId) {
    throw new Error(
      "Frame Conn cannot lock reactions without an active combat."
    );
  }


  this.actorReactionLocks.set(
    actorKey,
    {
      combatId,
      reason
    }
  );


  return true;
}


